diff --git a/apps/server/src/runtime/job-worker.mjs b/apps/server/src/runtime/job-worker.mjs
--- a/apps/server/src/runtime/job-worker.mjs
+++ b/apps/server/src/runtime/job-worker.mjs
@@ -10,7 +10,8 @@ export function runJob(job) {
-  const result = spawnSync(job.command, job.args, { encoding: "utf8" });
+  const timeoutMs = Number(process.env.WORKER_TIMEOUT_MS ?? 30000);
+  const result = spawnSync(job.command, job.args, { encoding: "utf8", timeout: timeoutMs });
   if (result.status !== 0) throw new Error(`job failed: ${result.status}`);
   return result.stdout;
 }
